WITH filtered AS (SELECT *, LOWER(merchant) AS merchant_lower, YEAR(txn_time) AS txn_time_year, COALESCE(merchant, 'OTHER') AS merchant_clean FROM transactions WHERE txn_time >= TO_TIMESTAMP('2023-05-01 03:00:00')) SELECT id, account_id, txn_type, amount, merchant, merchant_lower, AVG(txn_time_year) OVER (PARTITION BY account_id ORDER BY txn_time_year, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS txn_time_year_avg_3_prior, FIRST_VALUE(amount, TRUE) OVER (PARTITION BY txn_type, account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_amount, NTILE(4) OVER (ORDER BY txn_time_year DESC, id) AS txn_time_year_bucket FROM filtered
